def transform(g):
    n=len(g); m=len(g[0])
    # find 2x2 all-zero block
    seed=None
    for r in range(n-1):
        for c in range(m-1):
            if g[r][c]==g[r][c+1]==g[r+1][c]==g[r+1][c+1]==0:
                seed=(r,c)
    r0,c0=seed
    out=[row[:] for row in g]
    for r in range(n):
        for c in range(m):
            if (r in (r0,r0+1) or c in (c0,c0+1)) and g[r][c]!=2:
                out[r][c]=0
    return out
